# v1 setup_cmds (work[7] / judge[6]), verbatim: make OpenTTDLab cache the CDN manifest.yaml files
# (manifest-<sha256(url)[:16]>.yaml in the cache dir) and fall back to them when offline.
# Run once at image build time: python3 /path/patch_openttdlab.py
import pathlib, openttdlab; p = pathlib.Path(openttdlab.__file__); s = p.read_text(); old = "    def get_yaml(client, url):\n        return yaml.safe_load(get(client, url))\n"; new = "    def get_yaml(client, url):\n        import hashlib as _hl, os as _os\n        _cached = _os.path.join(get_cache_dir(), \"manifest-\" + _hl.sha256(url.encode()).hexdigest()[:16] + \".yaml\")\n        try:\n            content = get(client, url)\n        except Exception:\n            with open(_cached, \"rb\") as _f:\n                return yaml.safe_load(_f.read())\n        with open(_cached, \"wb\") as _f:\n            _f.write(content)\n        return yaml.safe_load(content)\n"; assert s.count(old) == 1; p.write_text(s.replace(old, new))
